//! Hosted linked-device onboarding. QR SVG is generated by the trusted server's
//! QR renderer; provider input is encoded as modules, never interpolated markup.
use api::{DevicePairing, Provider, add_existing_interface, pair_device, paired_device_status, unlink_device};
use dioxus::prelude::*;
use crate::components::button::{Button, ButtonSize, ButtonVariant};
use crate::error_message;

#[component]
pub(crate) fn PairDeviceForm(
    slug: String, project: String, provider: Provider,
    #[props(default)] existing: Option<String>,
    #[props(default)] bound: bool,
    on_added: EventHandler<()>,
) -> Element {
    let initial = existing.clone();
    let mut pairing = use_signal(move || initial.map(|connection| DevicePairing {
        connection, state: if bound { "idle" } else { "connecting" }.into(), identity: None, qr_svg: None, expires_at: 0, error: None,
    }));
    let mut busy = use_signal(|| false);
    let mut error = use_signal(|| None::<String>);
    let mut unlinked = use_signal(|| false);
    let poll_slug = slug.clone();
    use_future(move || {
        let slug = poll_slug.clone();
        async move {
            loop {
                futures_timer::Delay::new(std::time::Duration::from_secs(2)).await;
                if busy() || unlinked() { continue; }
                let Some(current) = pairing() else { continue; };
                if !["connecting", "pairing"].contains(&current.state.as_str()) { continue; }
                match paired_device_status(slug.clone(), current.connection, false).await {
                    Ok(state) => { pairing.set(Some(state)); error.set(None); },
                    Err(e) => error.set(Some(error_message(&e))),
                }
            }
        }
    });
    let start_slug = slug.clone();
    let unlink_slug = slug.clone();
    let bind_slug = slug.clone();
    let bind_project = project.clone();
    let current = pairing();
    rsx! {
        div { class: "paired-device",
            if !bound {
                p { "Link your {provider.name()} account" }
                p { class: "conn-meta", "Open {provider.name()} on your phone, choose Linked devices, and scan the code." }
            }
            if let Some(state) = current.clone() {
                div { role: "status", aria_live: "polite",
                    match state.state.as_str() {
                        "connected" => rsx! { p { "Connected as {state.identity.clone().unwrap_or_default()}" } },
                        "pairing" => rsx! { p { "Scan with your phone to connect" } },
                        "expired" => rsx! { p { "The pairing code expired. Unlink this attempt to generate a new code." } },
                        "disconnected" => rsx! { p { "Disconnected. Check the connection or unlink to pair again." } },
                        "idle" => rsx! { p { "Manage linked device" } },
                        _ => rsx! { p { "Connecting…" } },
                    }
                }
                if let Some(svg) = state.qr_svg {
                    div { class: "paired-qr", role: "img", aria_label: "Scan this QR code with the linked devices screen on your phone", dangerous_inner_html: svg }
                }
                if let Some(message) = state.error { p { class: "orgs-error", "{message}" } }
                div { class: "conn-actions",
                    if state.state == "connected" && !bound {
                        Button { disabled: busy(), onclick: move |_| {
                            let (slug, project, id) = (bind_slug.clone(), bind_project.clone(), pairing().unwrap().connection);
                            async move { busy.set(true);
                                match add_existing_interface(slug, project, id).await {
                                    Ok(_) => on_added.call(()), Err(e) => error.set(Some(error_message(&e))),
                                }
                                busy.set(false);
                            }
                        }, "Use for this project" }
                    }
                    Button { variant: ButtonVariant::Outline, size: ButtonSize::Sm, disabled: busy(), onclick: move |_| {
                        let (slug, id) = (start_slug.clone(), pairing().unwrap().connection);
                        async move { busy.set(true);
                            match paired_device_status(slug, id, true).await {
                                Ok(state) => { pairing.set(Some(state)); error.set(None); }, Err(e) => error.set(Some(error_message(&e))),
                            }
                            busy.set(false);
                        }
                    }, "Check connection" }
                    Button { variant: ButtonVariant::Destructive, size: ButtonSize::Sm, disabled: busy(), onclick: move |_| {
                        let (slug, id) = (unlink_slug.clone(), pairing().unwrap().connection);
                        async move { busy.set(true);
                            match unlink_device(slug, id).await {
                                Ok(()) => { unlinked.set(true); pairing.set(None); error.set(None); on_added.call(()); },
                                Err(e) => error.set(Some(error_message(&e))),
                            }
                            busy.set(false);
                        }
                    }, "Unlink device" }
                }
            } else {
                Button { disabled: busy(), onclick: move |_| {
                    let slug = slug.clone();
                    async move { busy.set(true); unlinked.set(false);
                        match pair_device(slug, provider).await {
                            Ok(state) => { pairing.set(Some(state)); error.set(None); }, Err(e) => error.set(Some(error_message(&e))),
                        }
                        busy.set(false);
                    }
                }, if busy() { "Preparing code…" } else { "Connect with QR code" } }
            }
            if let Some(message) = error() { p { class: "orgs-error", role: "alert", "{message}" } }
        }
    }
}
